<div class="permission-layout"><div><h3>Global permissions</h3><div class="permission-grid"><?php foreach([['create_vault','Create vaults'],['manage_platforms','Manage platforms'],['manage_backups','Manage backups'],['view_activity','View activity log']] as [$k,$label]): ?><label class="check-card"><input type="checkbox" name="perm[<?=$k?>]"><span><b><?=e($label)?></b><small><?=e(['create_vault'=>'Create new vaults','manage_platforms'=>'Add/remove platform entries','manage_settings'=>'Change security preferences','manage_backups'=>'Create and restore backups','view_activity'=>'See security activity','add_codes'=>'Add new recovery codes','mark_codes'=>'Mark a code used or unused','delete_codes'=>'Permanently delete recovery codes'][$k])?></small></span></label><?php endforeach; ?></div></div><div><h3>Vault & code permissions</h3><div class="permission-grid"><?php foreach([['reveal_codes','Reveal codes'],['copy_codes','Copy codes'],['add_codes','Add recovery codes'],['mark_codes','Mark codes used / unused'],['delete_codes','Delete recovery codes'],['edit_vaults','Edit vault details'],['delete_vaults','Delete vaults']] as [$k,$label]): ?><label class="check-card"><input type="checkbox" name="perm[<?=$k?>]"><span><b><?=e($label)?></b><small>Applies to assigned vaults.</small></span></label><?php endforeach; ?></div></div></div>
<label class="all-vaults-card"><input type="checkbox" name="all_vaults" value="1" data-all-vaults><span><b>Give access to all vaults</b><small>Includes every current and future vault, but only with the permissions checked above.</small></span></label>
<div class="vault-access-picker" data-vault-access-picker><div class="section-head"><div><h3>Vault access</h3><p>Select the vaults this user can open.</p></div></div><div class="vault-access-list"><?php foreach($vaults as $v): ?><label class="vault-access-item"><input type="checkbox" name="vaults[]" value="<?=$v['id']?>"><span><b><?=e($v['name'])?></b><small><?=e($v['account']?:$v['category'])?></small></span></label><?php endforeach; ?><?php if(!$vaults): ?><div class="empty">No vaults yet.</div><?php endif; ?></div></div>
<div class="user-form-footer"><span>The user can sign in with their own username and password.</span><button class="btn primary" type="submit">Create sub-user</button></div></form></section>
<?php endif; ?>

