<script>
(()=>{const all=document.querySelector('[data-all-vaults]'),picker=document.querySelector('[data-vault-access-picker]');function sync(){if(!all||!picker)return;picker.classList.toggle('disabled',all.checked);picker.querySelectorAll('input[type=checkbox]').forEach(x=>x.disabled=all.checked)}sync();all?.addEventListener('change',sync)})();
</script>
